var controller=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEditor.Animations.AnimatorController>("Assets/animetors/Sample Animator Controller.controller");
var clip=System.Linq.Enumerable.First(System.Linq.Enumerable.OfType<UnityEngine.AnimationClip>(UnityEditor.AssetDatabase.LoadAllAssetsAtPath("Assets/UnityChan/Animations/unitychan_WIN00.fbx")),c=>!c.name.StartsWith("__"));
var machine=controller.layers[0].stateMachine;var win=System.Linq.Enumerable.FirstOrDefault(machine.states,s=>s.state.name=="Win").state;if(win==null)win=machine.AddState("Win");win.motion=clip;win.speed=1;foreach(var t in win.transitions)win.RemoveTransition(t);UnityEditor.EditorUtility.SetDirty(win);UnityEditor.EditorUtility.SetDirty(controller);UnityEditor.AssetDatabase.SaveAssets();return "Win configured: "+clip.length;
